CREATE OR REPLACE FUNCTION public.guard_customer_catalog_settings() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('postgres','service_role','supabase_admin') OR public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'super_admin') THEN RETURN NEW; END IF; IF TG_OP='INSERT' THEN IF NEW.customer_only OR NEW.customer_key IS NOT NULL OR NEW.customer_visible IS NOT NULL THEN RAISE EXCEPTION 'Customer catalog requires platform administrator'; END IF; ELSE IF OLD.customer_only OR ROW(NEW.customer_visible,NEW.customer_room,NEW.customer_order,NEW.customer_category,NEW.customer_name,NEW.customer_size,NEW.customer_disposal_allowed,NEW.customer_only,NEW.customer_key,NEW.customer_deleted_at) IS DISTINCT FROM ROW(OLD.customer_visible,OLD.customer_room,OLD.customer_order,OLD.customer_category,OLD.customer_name,OLD.customer_size,OLD.customer_disposal_allowed,OLD.customer_only,OLD.customer_key,OLD.customer_deleted_at) THEN RAISE EXCEPTION 'Customer catalog requires platform administrator'; END IF; END IF; RETURN NEW; END $$;